import{_ as p,a0 as d,w as o,s as r,I as e,x as i,a1 as n,A as a,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何根據文件權限查找文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何根據文件權限查找文件 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何根據文件權限查找文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何根據文件權限查找文件 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171207 How To Find Files Based On their Permissions","title":"如何根據文件權限查找文件","tag":"201801","desc":""},"relativePath":"201801/20171207 How To Find Files Based On their Permissions.md","filePath":"[post].md"}'),h={name:"201801/20171207 How To Find Files Based On their Permissions.md"};function g(c,s,k,u,f,b){const t=d("Link");return o(),r("div",null,[s[22]||(s[22]=e("h1",{id:"如何根據文件權限查找文件",tabindex:"-1"},[i("如何根據文件權限查找文件 "),e("a",{class:"header-anchor",href:"#如何根據文件權限查找文件","aria-label":"Permalink to “如何根據文件權限查找文件”"},"​")],-1)),s[23]||(s[23]=e("p",null,[e("img",{src:"https://www.ostechnix.com/wp-content/uploads/2017/12/Find-Files-Based-On-their-Permissions-720x340.png",alt:""})],-1)),e("p",null,[s[1]||(s[1]=i("在 Linux 中查找文件並不是什麼大問題。市面上也有很多可靠的自由開源的可視化查找工具。但對我而言，查找文件，用命令列的方式會更快更簡單。我們已經知道 ",-1)),n(t,{href:"https://www.ostechnix.com/find-sort-files-based-access-modification-date-time-linux/"},{default:a(()=>[...s[0]||(s[0]=[i("如何根據訪問和修改文件的時間尋找或整理文件",-1)])]),_:1}),s[2]||(s[2]=i("。今天，在基於 Unix 的操作系統中，我們將見識如何通過權限查找文件。",-1))]),s[24]||(s[24]=l(`<p>本段教程中，我將創建三個文件名為 <code>file1</code>，<code>file2</code> 和 <code>file3</code> 分別賦予 <code>777</code>，<code>766</code> 和 <code>655</code> 文件權限，並分別置於名為 <code>ostechnix</code> 的文件夾中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir ostechnix &amp;&amp; cd ostechnix/</span></span>
<span class="line"><span>install -b -m 777 /dev/null file1</span></span>
<span class="line"><span>install -b -m 766 /dev/null file2</span></span>
<span class="line"><span>install -b -m 655 /dev/null file3</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2017/12/find-files-1-1.png" alt=""></p><p>現在，讓我們通過權限來查找一下文件。</p><h3 id="根據權限查找文件" tabindex="-1">根據權限查找文件 <a class="header-anchor" href="#根據權限查找文件" aria-label="Permalink to “根據權限查找文件”">​</a></h3><p>根據權限查找文件最具代表性的語法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find -perm mode</span></span></code></pre></div><p>mode 可以是代表權限的八進制數字（777、666 …）也可以是權限符號（u=x，a=r+x）。</p><p>在深入之前，我們就以下三點詳細説明 mode 參數。</p><ol><li>如果我們不指定任何參數前綴，它將會尋找<strong>具體</strong>權限的文件。</li><li>如果我們使用 <code>-</code> 參數前綴， 尋找到的文件至少擁有 mode 所述的權限，而不是具體的權限（大於或等於此權限的文件都會被查找出來）。</li><li>如果我們使用 <code>/</code> 參數前綴，那麼所有者、組或者其他人任意一個應當享有此文件的權限。</li></ol><p>為了讓你更好的理解，讓我舉些例子。</p><p>首先，我們將要看到基於數字權限查找文件。</p><h3 id="基於數字-八進制-權限查找文件" tabindex="-1">基於數字（八進制）權限查找文件 <a class="header-anchor" href="#基於數字-八進制-權限查找文件" aria-label="Permalink to “基於數字（八進制）權限查找文件”">​</a></h3><p>讓我們運行下列命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find -perm 777</span></span></code></pre></div><p>這條命令將會查找到當前目錄權限為<strong>確切為 777</strong> 權限的文件。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2017/12/find-files-2.png" alt="1"></p><p>如你看見的屏幕輸出，file1 是唯一一個擁有<strong>確切為 777 權限</strong>的文件。</p><p>現在，讓我們使用 <code>-</code> 參數前綴，看看會發生什麼。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find -perm -766</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2017/12/find-files-3.png" alt=""></p><p>如你所見，命令列上顯示兩個文件。我們給 file2 設置了 766 權限，但是命令列顯示兩個文件，什麼鬼？因為，我們設置了 <code>-</code> 參數前綴。它意味着這條命令將在所有文件中查找文件所有者的“讀/寫/執行”權限，文件用户組的“讀/寫”權限和其他用户的“讀/寫”權限。本例中，file1 和 file2 都符合要求。換句話説，文件並不一樣要求時確切的 766 權限。它將會顯示任何屬於（高於）此權限的文件 。</p><p>然後，讓我們使用 <code>/</code> 參數前置，看看會發生什麼。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find -perm /222</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2017/12/find-files-6.png" alt=""></p><p>上述命令將會查找某些人（要麼是所有者、用户組，要麼是其他人）擁有寫權限的文件。這裏有另外一個例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find -perm /220</span></span></code></pre></div><p>這條命令會查找所有者或用户組中擁有寫權限的文件。這意味着匹配所有者和用户組任一可寫的文件，而其他人的權限隨意。</p><p>如果你使用 <code>-</code> 前綴運行相同的命令，你只會看到所有者和用户組都擁有寫權限的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find -perm -220</span></span></code></pre></div><p>下面的截圖會告訴你這兩個參數前綴的不同。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2017/12/find-files-7.png" alt=""></p><p>如我之前説過的一樣，我們也可以使用符號表示文件權限。</p><p>請閲讀：</p>`,34)),e("ul",null,[e("li",null,[n(t,{href:"https://www.ostechnix.com/how-to-find-largest-and-smallest-directories-and-files-in-linux/"},{default:a(()=>[...s[3]||(s[3]=[i("如何在 Linux 中找到最大和最小的目錄和文件",-1)])]),_:1})]),e("li",null,[n(t,{href:"https://www.ostechnix.com/find-oldest-file-directory-tree-linux/"},{default:a(()=>[...s[4]||(s[4]=[i("如何在 Linux 的目錄樹中找到最老的文件",-1)])]),_:1})]),e("li",null,[n(t,{href:"https://www.ostechnix.com/find-files-bigger-smaller-x-size-linux/"},{default:a(()=>[...s[5]||(s[5]=[i("如何在 Linux 中找到超過或小於某個大小的文件",-1)])]),_:1})])]),s[25]||(s[25]=l(`<h3 id="基於符號的文件權限查找文件" tabindex="-1">基於符號的文件權限查找文件 <a class="header-anchor" href="#基於符號的文件權限查找文件" aria-label="Permalink to “基於符號的文件權限查找文件”">​</a></h3><p>在下面的例子中，我們使用例如 <code>u</code>（所有者）、<code>g</code>（用户組） 和 <code>o</code>（其他） 的符號表示法。我們也可以使用字母 <code>a</code> 代表上述三種類型。我們可以通過特指的 <code>r</code> （讀）、 <code>w</code> （寫）、 <code>x</code> （執行）分別代表它們的權限。</p><p>例如，尋找用户組中擁有 <code>寫</code> 權限的文件，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find -perm -g=w</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2017/12/find-files-8.png" alt=""></p><p>上面的例子中，file1 和 file2 都擁有 <code>寫</code> 權限。請注意，你可以等效使用 <code>=</code> 或 <code>+</code> 兩種符號標識。例如，下列兩行相同效果的代碼。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find -perm -g=w</span></span>
<span class="line"><span>find -perm -g+w</span></span></code></pre></div><p>查找文件所有者中擁有寫權限的文件，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find -perm -u=w</span></span></code></pre></div><p>查找所有用户中擁有寫權限的文件，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find -perm -a=w</span></span></code></pre></div><p>查找所有者和用户組中同時擁有寫權限的文件，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find -perm -g+w,u+w</span></span></code></pre></div><p>上述命令等效與 <code>find -perm -220</code>。</p><p>查找所有者或用户組中擁有寫權限的文件，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find -perm /u+w,g+w</span></span></code></pre></div><p>或者,</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find -perm /u=w,g=w</span></span></code></pre></div><p>上述命令等效於 <code>find -perm /220</code>。</p><p>更多詳情，參照 man 手冊。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man find</span></span></code></pre></div>`,21)),e("p",null,[s[7]||(s[7]=i("瞭解更多簡化案例或其他 Linux 命令，查看",-1)),n(t,{href:"https://www.ostechnix.com/3-good-alternatives-man-pages-every-linux-user-know/"},{default:a(()=>[...s[6]||(s[6]=[i("man 手冊",-1)])]),_:1}),s[8]||(s[8]=i("。",-1))]),s[26]||(s[26]=e("p",null,"然後，這就是所有的內容。希望這個教程有用。更多幹貨，敬請關注。",-1)),s[27]||(s[27]=e("p",null,"乾杯！",-1)),s[28]||(s[28]=e("hr",null,null,-1)),e("p",null,[s[10]||(s[10]=i("via: ",-1)),n(t,{href:"https://www.ostechnix.com/find-files-based-permissions/"},{default:a(()=>[...s[9]||(s[9]=[i("https://www.ostechnix.com/find-files-based-permissions/",-1)])]),_:1})]),e("p",null,[s[14]||(s[14]=i("作者：",-1)),n(t,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...s[11]||(s[11]=[i("SK",-1)])]),_:1}),s[15]||(s[15]=i(" 譯者：",-1)),n(t,{href:"https://github.com/CYLeft"},{default:a(()=>[...s[12]||(s[12]=[i("CYLeft",-1)])]),_:1}),s[16]||(s[16]=i(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:a(()=>[...s[13]||(s[13]=[i("wxy",-1)])]),_:1})]),e("p",null,[s[19]||(s[19]=i("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[17]||(s[17]=[i("LCTT",-1)])]),_:1}),s[20]||(s[20]=i(" 原創編譯，",-1)),n(t,{href:"https://linux.cn/"},{default:a(()=>[...s[18]||(s[18]=[i("Linux中國",-1)])]),_:1}),s[21]||(s[21]=i(" 榮譽推出",-1))])])}const C=p(h,[["render",g]]);export{x as __pageData,C as default};
